import { useMemo, useState } from 'react'
import { BookOpen, Search, ChevronDown, ChevronUp, Calculator, ClipboardCheck, Lightbulb, AlertTriangle } from 'lucide-react'
import ModuleGuide from './ModuleGuide'

type Topic = { title:string; purpose:string; inputs:string[]; method:string[]; formulas:string[]; example:string; checks:string[]; pitfalls:string[] }
type Chapter = { id:number; title:string; objective:string; topics:Topic[] }

const chapters:Chapter[] = [
{id:1,title:'تعریف پروژه و بازار',objective:'تثبیت مبنای مطالعه، محدوده پروژه، محل اجرا، محصول هدف و منطق تجاری سرمایه‌گذاری.',topics:[
{title:'۱-۱. شناسنامه و محدوده پروژه',purpose:'پروژه باید از ابتدا مرز فنی و اقتصادی روشنی داشته باشد؛ واحدهای داخل محدوده، واحدهای بیرون محدوده و نقاط اتصال به زیرساخت‌ها مشخص شوند.',inputs:['نام و شناسه پروژه، سرمایه‌گذار و شخصیت حقوقی','محل اجرا، وضعیت مالکیت زمین و دسترسی‌ها','مرحله پروژه: جدید، توسعه، نوسازی یا رفع گلوگاه','واحدهای داخل محدوده و خارج محدوده (Battery Limits)','سال مبنای قیمت‌ها، تاریخ تهیه مطالعه و افق تحلیل'],method:['ابتدا هدف سرمایه‌گذاری را در یک جمله بنویسید.','محصول نهایی و ظرفیت اسمی را مشخص کنید.','مرز پروژه را روی نمودار بلوکی یا فهرست واحدها ثبت کنید.','موارد خارج از محدوده اما ضروری مانند پست برق، خط گاز، جاده یا انبار را جداگانه تعیین تکلیف کنید.','تمام مبالغ را به سال قیمت‌گذاری واحد تبدیل کنید یا تعدیل زمانی آنها را مستند کنید.'],formulas:['ظرفیت طراحی = ظرفیت اسمی واحد اصلی × تعداد خطوط','سال مبنای قیمت = سالی که تمام CAPEX و OPEX به قیمت‌های آن بیان می‌شوند'],example:'برای یک خط نورد ورق تخت، محدوده می‌تواند از دریافت اسلب در انبار تا بسته‌بندی و تحویل ورق باشد. اگر تولید اسلب در محل انجام نمی‌شود، فولادسازی خارج از محدوده است؛ اما خرید اسلب، حمل داخلی و انبارش در هزینه‌های پروژه دیده می‌شود.',checks:['ظرفیت و محصول در تمام فصل‌های گزارش یکسان باشند.','مرز پروژه با تأمین‌کنندگان، شبکه برق، گاز و آب مشخص باشد.','واحد پول و سال مبنای قیمت‌ها در کل مدل یکسان باشد.'],pitfalls:['مخلوط‌کردن پروژه نورد مستقل با فولادسازی یا احیای مستقیم بدون تعریف محدوده و سرمایه‌گذاری آنها.','استفاده از قیمت‌های سال‌های متفاوت بدون تعدیل یا ثبت تاریخ منبع.']},
{title:'۱-۲. تحلیل بازار و فروش',purpose:'اثبات امکان فروش محصول با قیمت و ترکیب قابل دفاع؛ ظرفیت تولید به‌تنهایی دلیل توجیه‌پذیری نیست.',inputs:['مصرف ظاهری = تولید داخلی + واردات − صادرات','ظرفیت و تولید واقعی رقبا، واردات و صادرات','تقاضا به تفکیک گرید، ضخامت، عرض و شکل محصول','قیمت فروش درب کارخانه، هزینه حمل و شرایط تحویل','مشتریان هدف، سهم بازار قابل دستیابی و قراردادهای فروش'],method:['بازار را بر اساس خانواده محصول و مشخصات فنی بخش‌بندی کنید.','آمار تولید، تجارت و مصرف را از منابع مستقل جمع‌آوری کنید.','قیمت‌ها را هم‌زمان از نظر تاریخ، ارز، مالیات، حمل و شرایط تحویل هم‌مبنا کنید.','رقبای موجود و پروژه‌های در دست احداث را از عرضه قابل تحقق جدا کنید.','سهم بازار قابل دستیابی را با ظرفیت فروش، شبکه توزیع و کیفیت محصول محدود کنید.'],formulas:['مصرف ظاهری (تن) = تولید داخلی + واردات − صادرات ± تغییر موجودی (در صورت دسترسی)','نرخ رشد مرکب سالانه (CAGR) = (مقدار پایان / مقدار آغاز)^(1/n) − 1','فروش قابل تحقق = حداقلِ تولید قابل فروش، تقاضای هدف و ظرفیت جذب بازار','درآمد فروش = Σ (مقدار فروش محصول i × قیمت خالص فروش محصول i)'],example:'اگر ظرفیت فروش سالانه ۲۵۰ هزار تن باشد اما بازار هدف تنها ۱۸۰ هزار تن محصول با مشخصات موردنظر جذب کند، فروش مدل نباید بدون قرارداد یا تحلیل صادرات برابر ظرفیت اسمی فرض شود.',checks:['قیمت‌ها دارای منبع، تاریخ، ارز و شرایط تحویل باشند.','آمار واردات و صادرات دوباره‌شماری نشده باشد.','ظرفیت اسمی رقبا با تولید واقعی آنها اشتباه نشود.'],pitfalls:['فرض فروش ۱۰۰ درصد ظرفیت از سال اول بدون تحلیل Ramp-up.','استفاده از قیمت اعلامی بازار به‌جای قیمت خالص قابل تحقق پروژه.']},
{title:'۱-۳. منابع داده و قابلیت اتکا',purpose:'ردیابی‌پذیری مفروضات و تفکیک داده مستند از برآورد.',inputs:['نوع منبع: گزارش/مستند، داده واقعی، استعلام سازنده، برآورد مهندسی یا فرض کاربر','نام مرجع، شماره صفحه یا پیوند، تاریخ دریافت','واحد، ارز، محدوده فنی و سطح اطمینان'],method:['برای هر داده کلیدی یک منبع و تاریخ ثبت کنید.','در صورت تعارض منابع، هر دو مقدار و منطق انتخاب مقدار مبنا را بنویسید.','برای داده‌های حساس، مقدار حداقل/مبنا/حداکثر تعریف کنید.','فرض‌های موقت را با مسئول و موعد اعتبارسنجی ثبت کنید.'],formulas:['میانگین وزنی برآورد = Σ (وزن منبع i × مقدار منبع i) / Σ وزن‌ها','وزن اطمینان صرفاً ابزار رتبه‌بندی داخلی است و جایگزین کیفیت منبع یا تحلیل آماری نیست.'],example:'ظرفیت از کاتالوگ سازنده، مصرف انرژی از تضمین عملکرد، قیمت تجهیز از استعلام تاریخ‌دار و هزینه نصب از برآورد مهندسی ثبت شود؛ این چهار داده نباید همگی «داده واقعی» نام‌گذاری شوند.',checks:['برای CAPEX عمده و مصرف ویژه انرژی منبع مشخص وجود داشته باشد.','تاریخ و واحد منبع ثبت شده باشد.'],pitfalls:['تبدیل برآورد یا فرض به واقعیت قطعی در گزارش.']}
]},
{id:2,title:'محصول و ظرفیت تولید',objective:'تعریف سبد محصول، ظرفیت اسمی و عملی، برنامه تولید و محدودیت‌های کیفیت و بازار.',topics:[
{title:'۲-۱. تعریف سبد محصول و مشخصات',purpose:'محصول باید با مشخصات قابل تولید و قابل فروش تعریف شود.',inputs:['خانواده محصول و نام تجاری/استاندارد','گرید فولادی و دامنه ترکیب شیمیایی','ضخامت، عرض، طول یا قطر و وزن واحد','سهم هر محصول از ترکیب تولید (Product Mix)','قیمت و واحد فروش هر محصول'],method:['محصولات را به ردیف‌های مستقل با مشخصات فنی تفکیک کنید.','برای هر ردیف دامنه ابعادی و گرید مجاز را ثبت کنید.','درصد ترکیب محصول را به‌گونه‌ای تعیین کنید که جمع آن ۱۰۰ درصد باشد.','قابلیت واقعی خط و محدودیت تغییر محصول را کنترل کنید.'],formulas:['Σ سهم محصول i = 100%','مقدار تولید محصول i = تولید کل × سهم محصول i','میانگین وزنی قیمت فروش = Σ (سهم محصول i × قیمت محصول i)'],example:'در خط ورق تخت، ورق ۸ تا ۲۰ میلی‌متر و ورق ضخیم‌تر می‌توانند ردیف محصول جدا با سرعت، راندمان، قیمت و بازار متفاوت باشند؛ دامنه ابعادی باید با طراحی خط تطبیق داده شود.',checks:['جمع سهم محصولات دقیقاً ۱۰۰ درصد باشد.','مشخصات ابعادی از محدوده تضمین‌شده تجهیزات خارج نباشد.'],pitfalls:['تعریف محصول فقط با عنوان کلی «ورق» بدون تفکیک ضخامت، گرید و ابعاد.']},
{title:'۲-۲. ظرفیت اسمی، عملی و تولید قابل فروش',purpose:'تفکیک ظرفیت طراحی از تولید قابل تحقق در شرایط واقعی.',inputs:['ظرفیت اسمی خط (تن بر ساعت یا تن در سال)','ساعات تقویمی، توقف برنامه‌ریزی‌شده و اضطراری','Availability، عملکرد و کیفیت/بازده محصول','تعداد شیفت و روز کاری','دوره راه‌اندازی و منحنی افزایش ظرفیت'],method:['ظرفیت ساعتی و ساعات در دسترس را تعیین کنید.','توقف‌های برنامه‌ریزی‌شده و اضطراری را جدا ثبت کنید.','راندمان عبور مواد و محصول سالم را اعمال کنید.','برنامه Ramp-up سال‌های نخست را جداگانه تعریف کنید.'],formulas:['ساعات در دسترس = ساعات تقویمی − توقف برنامه‌ریزی‌شده − توقف اضطراری','ظرفیت عملی = ظرفیت ساعتی × ساعات در دسترس','تولید قابل فروش = ظرفیت عملی × ضریب بهره‌برداری × بازده کیفی','تولید سال t = ظرفیت عملی × ضریب Ramp-up سال t'],example:'اگر خط ۵۰ تن بر ساعت و ۶۲۰۰ ساعت مفید داشته باشد، ظرفیت قبل از اعمال بازده و محدودیت بازار ۳۱۰ هزار تن است؛ این عدد الزاماً برابر فروش یا محصول سالم نیست.',checks:['مبنای ساعات سالانه با تقویم شیفت و تعمیرات سازگار باشد.','Availability و Yield دوباره‌شماری نشوند.','Ramp-up از ۰ تا ۱۰۰ درصد و مستند باشد.'],pitfalls:['کسر توقفات از ساعات و سپس اعمال دوباره ضریب دسترس‌پذیری بدون تعریف دقیق.','یکسان فرض کردن ظرفیت طراحی، تولید سالم و فروش.']},
{title:'۲-۳. ضریب مصرف و بازده محصول',purpose:'اتصال تولید محصول به خوراک و ضایعات.',inputs:['مصرف ویژه اسلب/بیلت/بلوم','بازده نورد، پوسته اکسیدی، سر و ته، ضایعات برش','بازیافت ضایعات و نرخ برگشت به چرخه'],method:['مرز اندازه‌گیری مصرف را تعیین کنید: ورودی کوره، ورودی خط یا محصول نهایی.','افت‌های هر مرحله را جداگانه ثبت کنید.','ضایعات قابل فروش و ضایعات قابل برگشت را از هم جدا کنید.'],formulas:['بازده وزنی = وزن محصول سالم / وزن خوراک','خوراک موردنیاز = محصول سالم / بازده وزنی','ضایعات = خوراک − محصول سالم'],example:'برای تولید ۱۰۰ هزار تن محصول با بازده ۹۰ درصد، خوراک موردنیاز حدود ۱۱۱٬۱۱۱ تن است؛ ضایعات ۱۱٬۱۱۱ تن خواهد بود، پیش از کسر ارزش بازیافتی.',checks:['بازده بین صفر و ۱۰۰ درصد باشد.','مبنای ضریب مصرف با موازنه مواد مرحله ۳ یکسان باشد.'],pitfalls:['ثبت مصرف ویژه ۱٫۱ تن بر تن و اعمال دوباره افت ۱۰ درصدی.']}
]},
{id:3,title:'فرآیند و موازنه مواد',objective:'توصیف مسیر تولید، ظرفیت تجهیزات اصلی، موازنه جرم و نقاط کنترل عملکرد.',topics:[
{title:'۳-۱. انتخاب مسیر فرآیندی و فناوری',purpose:'انتخاب فناوری باید با محصول، ظرفیت، کیفیت، خوراک و هزینه چرخه عمر سازگار باشد.',inputs:['نمودار جریان فرآیند (PFD) و شرح فرآیند','فناوری و آرایش خطوط، تجهیزات اصلی و ظرفیت هر تجهیز','شرایط خوراک، محصول و نقاط اتصال','سطح اتوماسیون، کنترل کیفیت و الزامات ایمنی'],method:['مسیر فرآیند را از دریافت خوراک تا محصول نهایی ترسیم کنید.','تجهیزات گلوگاهی و ظرفیت نامی آنها را فهرست کنید.','گزینه‌های فناوری را از نظر کیفیت، انرژی، تعمیرات، سرمایه و خدمات مقایسه کنید.','فرض‌های طراحی و تضمین‌های عملکردی سازنده را ثبت کنید.'],formulas:['ظرفیت کل مسیر پیوسته = حداقل ظرفیت مؤثر تجهیزات سری','ظرفیت تجهیزات موازی = مجموع ظرفیت مؤثر تجهیزات موازی'],example:'در خط نورد ورق تخت، کوره پیش‌گرم، دی‌اسکیلر، قفسه نورد، میز خنک‌کاری، صاف‌کن و برش می‌توانند گلوگاه‌های متفاوت داشته باشند؛ ظرفیت کل را نباید صرفاً از ظرفیت قفسه نورد برداشت کرد.',checks:['نمودار فرآیند با فهرست تجهیزات و موازنه مواد سازگار باشد.','تجهیزات جانبی ضروری حذف نشده باشند.'],pitfalls:['انتخاب فناوری صرفاً بر اساس کمترین قیمت خرید.']},
{title:'۳-۲. موازنه جرم',purpose:'تطبیق ورودی، خروجی، ضایعات، موجودی و بازیافت برای کل خط و هر مرحله.',inputs:['خوراک به تفکیک نوع و کیفیت','محصول اصلی و محصولات جانبی','ضایعات، پوسته، براده و برگشتی','تغییر موجودی بین ابتدا و انتهای دوره'],method:['مبنای زمانی موازنه را مشخص کنید (ساعتی، روزانه یا سالانه).','برای هر واحد فرآیندی ورودی و خروجی را ثبت کنید.','جریان‌های برگشتی را فقط یک بار در مرز مناسب وارد کنید.','اختلاف موازنه را محاسبه و علت آن را توضیح دهید.'],formulas:['ورودی + تولید داخل = خروجی + مصرف داخل + اتلاف + تغییر موجودی','خطای موازنه (%) = (ورودی − خروجی خالص) / ورودی × 100','مصرف ویژه خوراک = مقدار خوراک / مقدار محصول سالم'],example:'در موازنه سالانه، ۱۱۲ هزار تن اسلب ورودی می‌تواند به ۱۰۰ هزار تن ورق سالم، ۸ هزار تن ضایعات قابل بازیافت و ۴ هزار تن افت/اکسید و سایر اتلاف‌ها منتهی شود. این اعداد صرفاً نمونه آموزشی‌اند.',checks:['جمع ورودی و خروجی با تلورانس مهندسی قابل قبول بسته شود.','ضایعات برگشتی دوباره به‌عنوان خوراک خارجی شمرده نشوند.'],pitfalls:['نادیده‌گرفتن تغییر موجودی یا جریان برگشتی.']},
{title:'۳-۳. تراز ظرفیت و گلوگاه',purpose:'اطمینان از اینکه همه تجهیزات اصلی می‌توانند برنامه تولید را پشتیبانی کنند.',inputs:['ظرفیت نامی و ظرفیت مؤثر هر تجهیز','زمان سیکل، توقف، تعویض محصول و محدودیت ابعادی','ظرفیت انبارش، حمل و بسته‌بندی'],method:['ظرفیت هر تجهیز را در شرایط واقعی و نه فقط کاتالوگ محاسبه کنید.','توقفات مشترک و مستقل را تفکیک کنید.','گلوگاه را در سبد محصول و سناریوهای مختلف بررسی کنید.'],formulas:['ظرفیت مؤثر تجهیز = ظرفیت نامی × ضریب دسترس‌پذیری × ضریب عملکرد','ظرفیت مسیر = کمینه ظرفیت مؤثر تجهیزات سری'],example:'اگر ظرفیت مؤثر کوره ۳۰۰ هزار تن و نورد ۲۷۰ هزار تن و بسته‌بندی ۲۸۰ هزار تن باشد، ظرفیت مسیر حداکثر ۲۷۰ هزار تن است.',checks:['ظرفیت تجهیزات بر مبنای خوراک یا محصول بودن یکسان‌سازی شود.','ظرفیت انبار و حمل نیز بررسی شود.'],pitfalls:['جمع‌کردن ظرفیت تجهیزات سری به‌جای یافتن کمترین ظرفیت.']}
]},
{id:4,title:'مصارف زیربنایی و فرآیندی',objective:'محاسبه تقاضای آب، برق، گاز و سایر یوتیلیتی‌ها و مواد مصرفی به تفکیک نوع و واحد.',topics:[
{title:'۴-۱. یوتیلیتی‌های زیربنایی',purpose:'برآورد ظرفیت اتصال و هزینه مصرف آب، برق، گاز و زیرساخت‌های عمومی.',inputs:['برق: توان پیک (MW)، انرژی (kWh/y) و ضریب بار','گاز: دبی پیک و مصرف سالانه (Nm³/y)','آب خام، صنعتی، خنک‌کاری و تصفیه‌شده (m³/y)','هوا، بخار، اکسیژن و سایر خدمات عمومی در صورت نیاز'],method:['برای هر مصرف‌کننده، بار متصل و ساعات کار را تعیین کنید.','مصرف لحظه‌ای/پیک را از مصرف سالانه جدا کنید.','تلفات شبکه، ضریب هم‌زمانی و ظرفیت رزرو را لحاظ کنید.','هزینه خرید، آبونمان، دیماند و هزینه تصفیه را جداگانه ثبت کنید.'],formulas:['انرژی سالانه (kWh) = توان متوسط (kW) × ساعات کار','توان متوسط = توان پیک × ضریب بار','مصرف ویژه = مصرف سالانه یوتیلیتی / تن محصول سالم','هزینه برق = انرژی مصرفی × تعرفه انرژی + دیماند + هزینه‌های ثابت'],example:'برای مصرف ویژه برق ۱۲۰ kWh/t و تولید سالم ۲۰۰ هزار تن، انرژی سالانه ۲۴ میلیون kWh است؛ هزینه پیک و دیماند باید جدا بررسی شود.',checks:['واحد توان kW/MW با انرژی kWh/MWh اشتباه نشود.','مصرف پیک برای سایزینگ اتصال و مصرف سالانه برای OPEX استفاده شود.'],pitfalls:['تبدیل MW به kWh بدون لحاظ ساعات کار.','نادیده گرفتن هزینه دیماند، تصفیه و انتقال.']},
{title:'۴-۲. مواد و اقلام مصرفی فرآیندی',purpose:'محاسبه مواد مستقیم تولید و هزینه‌های وابسته به تناژ محصول.',inputs:['اسلب، بیلت یا خوراک اصلی','غلتک، روغن، گریس، نسوز، الکترود، مواد شیمیایی و قطعات مصرفی','نرخ مصرف ویژه، قیمت، واحد و تناوب مصرف','موجودی اطمینان و ضایعات'],method:['مواد مستقیم را از یوتیلیتی عمومی جدا کنید.','برای هر قلم نرخ مصرف به ازای تن محصول یا ساعت کار ثبت کنید.','قیمت را با ارز، تاریخ، حمل و شرایط تحویل مستند کنید.','اقلام سرمایه‌ای/قطعات یدکی راهبردی را با مواد مصرفی اشتباه نگیرید.'],formulas:['مصرف سالانه قلم i = نرخ مصرف ویژه i × مبنای فعالیت','هزینه سالانه قلم i = مصرف سالانه i × قیمت واحد','OPEX فرآیندی = Σ هزینه اقلام مصرفی فرآیندی'],example:'اگر مصرف روغن ۰٫۰۸ kg/t و تولید ۲۰۰ هزار تن باشد، مصرف سالانه ۱۶ هزار کیلوگرم است؛ مقدار واقعی باید از طراحی و تجربه عملیاتی یا تضمین سازنده گرفته شود.',checks:['واحد مصرف ویژه و واحد قیمت هم‌خوان باشند.','قلم اسلب در موازنه مواد و هزینه خوراک دو بار محاسبه نشود.'],pitfalls:['ثبت قطعات یدکی سرمایه‌ای به‌عنوان مصرف سالانه بدون منطق تعویض.']},
{title:'۴-۳. تعرفه و هزینه تأمین',purpose:'تبدیل مصرف فنی به هزینه قابل پیش‌بینی و بررسی ریسک دسترسی.',inputs:['تعرفه پایه و پلکانی، فصل و ساعت اوج','هزینه اتصال و توسعه شبکه','قیمت قراردادی یا سناریوی قیمت انرژی و مواد','محدودیت قطع، سهمیه و پایداری تأمین'],method:['تعرفه هر حامل را با تاریخ اعتبار ثبت کنید.','هزینه ثابت، متغیر، دیماند و سرمایه‌گذاری اتصال را جدا کنید.','سناریوی کمبود یا محدودیت انرژی را در ظرفیت تولید منعکس کنید.'],formulas:['هزینه یوتیلیتی = Σ (مصرف دوره × تعرفه همان دوره) + هزینه ثابت','هزینه ویژه یوتیلیتی = کل هزینه یوتیلیتی / تن محصول سالم'],example:'اگر محدودیت گاز در زمستان باعث کاهش ساعات کار شود، اثر آن فقط افزایش هزینه گاز نیست؛ باید کاهش تولید، فروش و سرمایه در گردش نیز در سناریو لحاظ شود.',checks:['تعرفه به‌روز و مربوط به گروه صنعتی صحیح باشد.','هزینه اتصال با مصرف عملیاتی مخلوط نشده باشد.'],pitfalls:['فرض دسترسی ۲۴ ساعته و بدون محدودیت به حامل انرژی.']}
]},
{id:5,title:'هزینه‌های ساخت و بهره‌برداری',objective:'تدوین CAPEX و OPEX کامل، مستند و زمان‌بندی‌شده به ارز پایه پروژه.',topics:[
{title:'۵-۱. سرمایه‌گذاری ثابت (CAPEX)',purpose:'برآورد هزینه ایجاد دارایی‌های لازم تا آماده بهره‌برداری.',inputs:['زمین: مساحت و قیمت واحد','ساختمان و ابنیه: نوع، زیربنا و قیمت واحد','ماشین‌آلات داخلی و خارجی','حمل، بیمه، گمرک، ترخیص، نصب و راه‌اندازی','مهندسی، مدیریت پروژه، زیرساخت و ذخیره احتیاطی','هزینه‌های پیش‌راه‌اندازی و سرمایه در گردش اولیه'],method:['WBS هزینه را بر اساس بسته کاری و گروه دارایی بسازید.','برای زمین و ساختمان مقدار × نرخ واحد را ثبت کنید.','برای هر تجهیز منشأ تأمین و ارز قیمت‌گذاری را مستقل تعیین کنید.','برای خرید خارجی قیمت پایه، نرخ ارز، حمل، بیمه، گمرک و نصب را تفکیک کنید.','زمان پرداخت و سال ساخت هر قلم را در برنامه CAPEX توزیع کنید.','ذخیره احتیاطی را بر اساس سطح طراحی و ریسک تعریف کنید، نه به‌صورت پنهان در قیمت اقلام.'],formulas:['هزینه پایه = مقدار × قیمت واحد','هزینه تجهیز وارداتی = قیمت ارزی × نرخ تبدیل + حمل و بیمه + گمرک و ترخیص + نصب','CAPEX کل = زمین + ساختمان + تجهیزات + نصب + مهندسی + هزینه‌های غیرمستقیم + پیش‌راه‌اندازی','CAPEX سال t = CAPEX کل × درصد تخصیص سال t','Σ درصد تخصیص سال‌های ساخت = 100%'],example:'ماشین‌آلات خارجی می‌توانند با قیمت یورویی و ماشین‌آلات ساخت داخل با قیمت دلاری ثبت شوند؛ منشأ خرید (داخلی/خارجی) و ارز قیمت‌گذاری دو فیلد مستقل‌اند.',checks:['تمام اقلام CAPEX واحد پول و تاریخ قیمت دارند.','جمع درصد برنامه سالانه دقیقاً ۱۰۰ درصد است.','زمین، مالیات قابل بازیافت و سرمایه در گردش با طبقه‌بندی صحیح ثبت شده‌اند.'],pitfalls:['حذف هزینه‌های نصب، مهندسی، قطعات اولیه و اتصال زیرساخت.','استفاده از نرخ ارز نامشخص یا اعمال دوباره آن.']},
{title:'۵-۲. هزینه‌های بهره‌برداری (OPEX)',purpose:'برآورد هزینه سالانه پایدار و تفکیک هزینه‌های ثابت و متغیر.',inputs:['مواد اولیه و مواد مصرفی فرآیندی','آب، برق، گاز و خدمات عمومی','نیروی انسانی، تعمیرات و نگهداری','بیمه، اداری، فروش، حمل و سربار','هزینه‌های زیست‌محیطی و دفع پسماند'],method:['هزینه‌ها را بر اساس ماهیت و محرک هزینه طبقه‌بندی کنید.','هزینه متغیر را به تناژ یا ساعات تولید پیوند دهید.','هزینه ثابت را برای ظرفیت و دوره مربوط تعریف کنید.','تورم، نرخ ارز و تغییر تعرفه را در مفروضات جداگانه وارد کنید.','از ثبت هم‌زمان یک قلم در مصارف فرآیندی و OPEX جلوگیری کنید.'],formulas:['OPEX متغیر = Σ (مقدار تولید × مصرف ویژه i × قیمت واحد i)','OPEX ثابت = حقوق ثابت + تعمیرات پایه + بیمه + اداری و سایر هزینه‌های ثابت','OPEX کل = OPEX ثابت + OPEX متغیر','هزینه عملیاتی ویژه = OPEX کل / تن محصول سالم'],example:'هزینه اسلب با تناژ خوراک و بازده مرتبط است؛ حقوق پرسنل شیفتی می‌تواند در دامنه ظرفیت مشخص نسبتاً ثابت باشد؛ برق ممکن است بخش انرژی متغیر و بخش دیماند ثابت داشته باشد.',checks:['CAPEX و OPEX مخلوط نشده باشند.','هزینه‌های مواد و یوتیلیتی دوباره شماری نشده باشند.','هزینه تعمیرات با برنامه توقف و ساعات کار سازگار باشد.'],pitfalls:['فرض درصد ثابت OPEX بدون بررسی محرک هزینه‌ها.','نادیده گرفتن هزینه فروش، حمل، بیمه و محیط زیست.']},
{title:'۵-۳. سرمایه در گردش و استهلاک',purpose:'محاسبه منابع نقدی موردنیاز عملیات و هزینه استهلاک دارایی‌ها.',inputs:['روزهای موجودی مواد اولیه و محصول','دوره وصول مطالبات و پرداخت بدهی‌ها','دارایی‌های قابل استهلاک، عمر مفید و ارزش اسقاط','روش استهلاک و زمان آماده بهره‌برداری'],method:['چرخه نقدی عملیات را از موجودی تا وصول فروش محاسبه کنید.','سرمایه در گردش را با تراز اقلام عملیاتی برآورد کنید.','دارایی‌ها را بر اساس عمر و زمان بهره‌برداری گروه‌بندی کنید.','روش و مبنای مالیاتی استهلاک را با مقررات قابل اعمال تطبیق دهید.'],formulas:['چرخه تبدیل وجه نقد = روز موجودی + روز مطالبات − روز پرداختنی','NWC = موجودی + مطالبات عملیاتی − بدهی‌های عملیاتی','تغییر NWC سال t = NWC(t) − NWC(t−1)','استهلاک خط مستقیم سالانه = (بهای تمام‌شده − ارزش اسقاط) / عمر مفید'],example:'اگر NWC بر مبنای ۳۰ روز هزینه/فروش عملیاتی محاسبه شود، آزادسازی آن در پایان عمر پروژه می‌تواند در جریان نقدی پایانی منعکس شود؛ مبنای روزها باید دقیق و شفاف باشد.',checks:['NWC در جریان نقدی به‌صورت تغییر سالانه اعمال شود، نه کل مانده هر سال.','استهلاک از زمان آماده بهره‌برداری آغاز شود.'],pitfalls:['کسر اصل وام از OPEX یا سود عملیاتی.','ثبت کل NWC به‌عنوان هزینه مصرف‌شده.']}
]},
{id:6,title:'تأمین مالی و نرخ تنزیل',objective:'تعریف ساختار سرمایه، تسهیلات، هزینه سرمایه و روش تنزیل متناسب با نوع جریان نقدی.',topics:[
{title:'۶-۱. ساختار سرمایه و منابع تأمین',purpose:'تفکیک آورده سهامداران، وام، تسهیلات ارزی، کمک‌ها و سایر منابع.',inputs:['کل سرمایه‌گذاری و زمان نیاز نقدی','درصد و مبلغ آورده سهامداران','مبلغ، ارز، نرخ، کارمزد و زمان برداشت هر وام','دوره تنفس، سررسید و روش بازپرداخت','وثایق، محدودیت‌ها و تعهدات مالی'],method:['منابع را به تفکیک ابزار و سال ثبت کنید.','ارز وام و نرخ تبدیل هر برداشت را مشخص کنید.','دوره تنفس اصل را از پرداخت یا سرمایه‌ای‌شدن بهره تفکیک کنید.','برنامه بازپرداخت را با جریان نقدی عملیاتی و CAPEX تطبیق دهید.'],formulas:['وزن حقوق صاحبان سهام = E / (D + E)','وزن بدهی = D / (D + E)','مانده پایان دوره = مانده ابتدای دوره + برداشت − بازپرداخت اصل','بهره دوره = مانده مشمول بهره × نرخ بهره دوره'],example:'در وام با تنفس اصل، ممکن است اصل وام بازپرداخت نشود اما بهره نقدی پرداخت شود. سرمایه‌ای‌شدن بهره فقط وقتی مجاز است که مدل آن را به بهای دارایی و استهلاک متصل کند؛ در غیر این صورت باید بهره نقدی منظور شود.',checks:['جمع منابع با مصارف و زمان‌بندی آنها تطبیق داشته باشد.','بازپرداخت اصل به‌عنوان هزینه سود و زیان ثبت نشود.','وام ارزی با نرخ ارز و ریسک ارزی مستقل مدل شود.'],pitfalls:['یکی گرفتن تنفس اصل با معافیت از پرداخت بهره.','فرض تأمین مالی قطعی برای وامی که صرفاً مذاکره شده است.']},
{title:'۶-۲. نرخ تنزیل دستی و WACC',purpose:'انتخاب نرخ تنزیل سازگار با نوع جریان نقدی و ریسک پروژه.',inputs:['نرخ بازده مورد انتظار حقوق صاحبان سهام (Ke)','هزینه بدهی پیش از مالیات (Kd)','نرخ مالیات مؤثر (T)','ارزش بازار/مبنای وزنی حقوق صاحبان سهام و بدهی','ریسک کشور، صنعت، پروژه و ارز جریان نقدی'],method:['در حالت دستی، نرخ تنزیل را همراه با دلیل و منبع وارد کنید.','در حالت محاسباتی، وزن بدهی و حقوق صاحبان سهام را تعریف کنید.','هزینه بدهی را پس از مالیات در WACC لحاظ کنید.','نرخ تنزیل را با ارز اسمی/واقعی و نوع جریان نقدی هم‌خوان کنید.','WACC محاسباتی را با ساختار واقعی تسهیلات و سرمایه تطبیق دهید.'],formulas:['WACC = (E/(D+E)) × Ke + (D/(D+E)) × Kd × (1−T)','هزینه بدهی پس از مالیات = Kd × (1−T)','نرخ واقعی = (1 + نرخ اسمی) / (1 + تورم) − 1'],example:'اگر E=60، D=40، Ke=35%، Kd=23% و T=20% باشد، WACC برابر ۰٫۶×۳۵٪ + ۰٫۴×۲۳٪×۰٫۸ = ۲۸٫۳۶٪ است. این مثال آموزشی است؛ نرخ‌ها باید مستند و متناسب با پروژه باشند.',checks:['وزن E و D جمعاً ۱۰۰ درصد شود.','WACC برای جریان نقدی آزاد پروژه و نرخ حقوق صاحبان سهام برای جریان نقدی سهامدار به‌کار رود.','نرخ و جریان نقدی هر دو هم‌ارز و هم‌مبنای تورمی باشند.'],pitfalls:['تنزیل جریان نقدی سهامدار با WACC بدون توجیه.','استفاده از نرخ ریالی برای جریان نقدی دلاری یا برعکس.']},
{title:'۶-۳. برنامه بازپرداخت و توان خدمت بدهی',purpose:'بررسی توان پروژه برای پرداخت بهره و اصل بدهی در موعد مقرر.',inputs:['مانده اول دوره و برداشت وام','نرخ بهره، کارمزد و روش بازپرداخت','اصل مساوی، اقساط مساوی یا بالون','جریان نقدی قابل استفاده برای خدمت بدهی'],method:['برای هر تسهیلات جدول سالانه بسازید.','برداشت، بهره، اصل و کارمزد را جداگانه محاسبه کنید.','دوره تنفس و سررسید را کنترل کنید.','DSCR را برای هر سال دارای خدمت بدهی محاسبه و سال بحرانی را مشخص کنید.'],formulas:['خدمت بدهی = اصل بازپرداختی + بهره + کارمزد','DSCR = جریان نقدی در دسترس خدمت بدهی (CFADS) / خدمت بدهی','مانده بدهی پایان سال = مانده اول سال + برداشت − اصل بازپرداختی'],example:'DSCR کمتر از ۱ یعنی جریان نقدی تعریف‌شده برای خدمت بدهی کافی نیست. آستانه ۱٫۲۰ فقط غربالگری اولیه است و جایگزین تعهدات وام‌دهنده نیست.',checks:['جمع بازپرداخت اصل از مبلغ برداشت‌شده بیشتر نشود.','DSCR سالانه و حداقل DSCR گزارش شود.','منبع CFADS دقیقاً تعریف شده باشد.'],pitfalls:['محاسبه DSCR با EBITDA بدون تعدیلات لازم برای مالیات، سرمایه در گردش و CAPEX نگهداری.']}
]},
{id:7,title:'جریان نقدی و شاخص‌های مالی',objective:'تبدیل مفروضات فنی و اقتصادی به جریان نقدی دوره‌ای و شاخص‌های تصمیم‌گیری.',topics:[
{title:'۷-۱. صورت سود و زیان پیش‌بینی‌شده',purpose:'محاسبه سود عملیاتی، مالیات و سود خالص با طبقه‌بندی درست هزینه‌ها.',inputs:['مقدار و قیمت فروش','هزینه‌های عملیاتی','استهلاک','هزینه مالی بهره و کارمزد','نرخ و مبنای مالیات'],method:['درآمد فروش را برای هر محصول محاسبه کنید.','بهای مواد و OPEX را از استهلاک جدا کنید.','EBIT را پیش از هزینه مالی محاسبه کنید.','بهره و کارمزد را در بخش مالی ثبت کنید.','مالیات را بر مبنای سود مشمول مالیات و قواعد زیان انتقالی محاسبه کنید.'],formulas:['درآمد = Σ مقدار فروش i × قیمت خالص i','EBITDA = درآمد − هزینه‌های نقدی عملیاتی','EBIT = EBITDA − استهلاک','EBT = EBIT − هزینه مالی','سود خالص = EBT − مالیات'],example:'بازپرداخت اصل وام در صورت سود و زیان هزینه نیست؛ فقط بهره و هزینه‌های مالی مرتبط در محاسبه سود قبل از مالیات اثر می‌گذارند.',checks:['اصل وام در OPEX یا هزینه مالی قرار نگرفته باشد.','استهلاک با CAPEX و عمر مفید سازگار باشد.'],pitfalls:['یکی گرفتن EBITDA با جریان نقدی آزاد.']},
{title:'۷-۲. جریان نقدی پروژه و سهامدار',purpose:'ارزیابی جداگانه جذابیت اقتصادی دارایی و بازده سرمایه‌گذار پس از تأمین مالی.',inputs:['EBIT یا EBITDA، مالیات و استهلاک','CAPEX و تغییر سرمایه در گردش','برداشت و بازپرداخت بدهی، بهره و کارمزد','ارزش اسقاط و بازیافت سرمایه در گردش'],method:['جریان نقدی پروژه را بدون ورود وام و پرداخت اصل بدهی بسازید.','مالیات عملیاتی پروژه را با منطق بدون اهرم مالی محاسبه کنید.','جریان نقدی سهامدار را پس از تأمین مالی و خدمت بدهی محاسبه کنید.','ارزش پایانی و بازیافت سرمایه در گردش را فقط در سال پایانی و با پشتوانه ثبت کنید.'],formulas:['FCF پروژه = EBIT×(1−T) + استهلاک − CAPEX − ΔNWC + ارزش پایانی','معادل: FCF پروژه = EBITDA − مالیات عملیاتی − CAPEX − ΔNWC + ارزش پایانی','جریان نقدی سهامدار = جریان نقدی عملیاتی پس از بهره و مالیات − CAPEX + برداشت وام − بازپرداخت اصل − کارمزد − ΔNWC + ارزش پایانی','NPV = Σ CF_t / (1+r)^t'],example:'ورود وام در جریان نقدی پروژه مجاز نیست؛ وام منبع تأمین مالی است و فقط در جریان نقدی سهامدار وارد می‌شود. این تفکیک از دوباره‌شماری منافع تأمین مالی جلوگیری می‌کند.',checks:['جریان نقدی پروژه از تسهیلات مستقل باشد.','جریان نقدی سهامدار تمام برداشت‌ها و بازپرداخت‌ها را منعکس کند.','سال صفر و زمان‌بندی CAPEX و بهره‌برداری روشن باشد.'],pitfalls:['افزودن وام به FCF پروژه و سپس تنزیل آن با WACC.','کسر اصل وام از سود عملیاتی.']},
{title:'۷-۳. NPV، IRR، PI و دوره بازگشت',purpose:'سنجش ارزش‌آفرینی، نرخ بازده و سرعت بازگشت سرمایه.',inputs:['جریان نقدی با علامت صحیح و دوره‌های منظم','نرخ تنزیل سازگار با جریان نقدی','سرمایه‌گذاری اولیه و جریان‌های پایانی'],method:['NPV را در نرخ تنزیل مبنا محاسبه کنید.','IRR را فقط در صورت وجود جریان نقدی با علامت‌های مناسب تفسیر کنید.','PI را با تعریف دقیق و مخرج سرمایه‌گذاری تنزیل‌شده محاسبه کنید.','دوره بازگشت ساده و تنزیل‌شده را جدا گزارش کنید.'],formulas:['NPV = Σ(t=0 تا n) CF_t/(1+r)^t','IRR: نرخی که NPV(r)=0','PI = ارزش فعلی جریان‌های نقدی مثبت / ارزش فعلی مخارج سرمایه‌گذاری','دوره بازگشت ساده: اولین زمان تجمع جریان نقدی نامنفی شود','دوره بازگشت تنزیل‌شده: اولین زمان تجمع جریان نقدی تنزیل‌شده نامنفی شود'],example:'NPV مثبت در نرخ تنزیل منتخب به معنی ایجاد ارزش نسبت به آن نرخ است؛ IRR به‌تنهایی معیار کافی نیست، به‌ویژه در جریان‌های نقدی با چند تغییر علامت.',checks:['واحد نرخ و دوره (سالانه/ماهانه) یکسان باشد.','جریان نقدی سال صفر در توان صفر تنزیل شود.','در صورت نبود IRR معتبر، مقدار ساختگی نمایش داده نشود.'],pitfalls:['تفسیر IRR بدون بررسی NPV و ساختار جریان نقدی.','مقایسه پروژه‌های با مقیاس متفاوت فقط بر اساس IRR.']},
{title:'۷-۴. تحلیل حساسیت و سناریو',purpose:'شناسایی محرک‌های اصلی ارزش پروژه و نقاط شکست اقتصادی.',inputs:['قیمت فروش، نرخ ارز و قیمت خوراک','CAPEX، OPEX و زمان ساخت','ظرفیت، بازده، Ramp-up و نرخ تنزیل'],method:['سناریوی پایه را تثبیت کنید.','هر بار یک متغیر را در دامنه منطقی تغییر دهید.','سناریوهای ترکیبی خوش‌بینانه، پایه و بدبینانه بسازید.','اثر هر سناریو بر NPV، IRR، DSCR و نقدینگی را گزارش کنید.'],formulas:['حساسیت NPV (%) = (NPV سناریو − NPV پایه) / |NPV پایه| × 100','نقطه سربه‌سر قیمت/ظرفیت: مقداری که NPV یا سود عملیاتی به آستانه تعریف‌شده برسد'],example:'افزایش ۱۰ درصدی قیمت اسلب ممکن است از کاهش ۱۰ درصدی هزینه اداری اثر بسیار بزرگ‌تری بر NPV داشته باشد؛ تحلیل حساسیت این محرک‌ها را رتبه‌بندی می‌کند.',checks:['دامنه سناریوها مستند و معقول باشد.','تغییر یک متغیر با سایر فرض‌های وابسته سازگار باشد.'],pitfalls:['تغییر مستقل متغیرهای به‌هم‌وابسته مانند ارز، قیمت خوراک و فروش بدون سناریوی کلان.']}
]},
{id:8,title:'نتیجه نهایی و توصیه تصمیم‌گیری',objective:'تبدیل نتایج فنی، بازار، مالی و ریسک به توصیه روشن و مشروط برای تصمیم‌گیرنده.',topics:[
{title:'۸-۱. جمع‌بندی شاخص‌ها و شروط تصمیم',purpose:'ارائه تصویر واحد از جذابیت اقتصادی، توان بازپرداخت و کیفیت اطلاعات.',inputs:['NPV و IRR پروژه','NPV و IRR سهامدار','PI و دوره بازگشت ساده/تنزیل‌شده','حداقل و میانگین DSCR و سال بحرانی','ریسک‌های بازار، فناوری، خوراک، انرژی، ارز و اجرا'],method:['نتایج فنی و بازار را پیش از شاخص‌های مالی مرور کنید.','شاخص‌های پروژه را از شاخص‌های سهامدار جدا نمایش دهید.','محدودیت‌ها و داده‌های با اطمینان پایین را صریح بنویسید.','توصیه را به شروط مشخص مانند قرارداد خوراک، فروش یا تأمین مالی گره بزنید.'],formulas:['شرط غربالگری NPV: NPV > 0 در نرخ تنزیل معتبر','شرط غربالگری PI: PI > 1 با تعریف نسبت منافع به مخارج','شرط توان بدهی: DSCR سال‌های خدمت بدهی مطابق حد قراردادی و در هر حال بیش از ۱ برای پوشش پایه'],example:'پروژه ممکن است NPV مثبت داشته باشد اما در سال دوم DSCR ضعیف باشد؛ توصیه می‌تواند «اقتصادی، مشروط به اصلاح ساختار بدهی و دوره تنفس» باشد، نه تأیید بی‌قیدوشرط.',checks:['توصیه با داده‌های ورودی و محدودیت‌ها سازگار باشد.','آستانه‌های DSCR و بازده به‌عنوان معیار غربالگری معرفی شوند، نه قانون همگانی.'],pitfalls:['صدور توصیه قطعی با داده ناقص یا قیمت‌های غیرقابل اتکا.']},
{title:'۸-۲. برنامه اقدام و شکاف اطلاعاتی',purpose:'تبدیل مطالعه به فهرست اقدامات قابل پیگیری برای امکان‌سنجی تفصیلی یا تصمیم نهایی.',inputs:['اطلاعات ناقص و مسئول تکمیل','استعلام‌های لازم و مهلت دریافت','مطالعات ژئوتکنیک، محیط زیست، اتصال انرژی و مجوزها','مذاکرات تأمین مالی و فروش'],method:['شکاف‌ها را بر اساس اثر بر NPV، برنامه زمان‌بندی و ریسک رتبه‌بندی کنید.','برای هر اقدام مسئول، موعد و مدرک خروجی تعیین کنید.','فرض‌های حساس را پیش از تصمیم نهایی اعتبارسنجی کنید.'],formulas:['اولویت اقدام = اثر بالقوه بر ارزش/ریسک × فوریت × میزان عدم‌قطعیت (مقیاس رتبه‌ای تعریف‌شده)'],example:'اگر قیمت اسلب و ظرفیت واقعی بازار دو محرک اصلی NPV باشند، دریافت قرارداد/استعلام معتبر این دو باید پیش از سفارش تجهیزات اولویت داشته باشد.',checks:['هر توصیه به اقدام مشخص و قابل سنجش تبدیل شده باشد.','مسئول و موعد برای شکاف‌های مهم تعیین شود.'],pitfalls:['پایان گزارش با توصیه کلی مانند «مطالعات بیشتر انجام شود» بدون برنامه اقدام.']}
]},
{id:9,title:'استاندارد خروجی‌ها و قواعد محاسباتی',objective:'تفکیک جریان نقدی برنامه‌ریزی مالی، بازده کل سرمایه و بازده حقوق صاحبان سهام؛ کنترل سازگاری نتایج با راهنمای مرجع محاسبات مالی.',topics:[
{title:'۹-۱. جریان نقدی برنامه‌ریزی مالی در برابر جریان نقدی ارزیابی',purpose:'جریان نقدی تأمین مالی و نقدینگی شرکت با جریان نقدی اقتصادی دارایی‌های پروژه یکسان نیستند.',inputs:['دریافت و پرداخت عملیاتی، سایر درآمدها و هزینه‌ها','افزایش دارایی ثابت و مخارج پیش از تولید','تغییر خالص سرمایه در گردش','برداشت و بازپرداخت اصل وام، بهره و کارمزد','آورده سهامداران، بازپرداخت سرمایه و سود تقسیمی','مالیات نقدی و ارزش اسقاط/بازیافت انتهای عمر'],method:['جدول Cash Flow for Financial Planning را برای کفایت نقدینگی و زمان‌بندی منابع بسازید.','برای بازده کل سرمایه، دریافت/پرداخت‌های تأمین مالی شامل آورده، برداشت و بازپرداخت وام، بهره و سود تقسیمی را حذف کنید.','سرمایه‌گذاری ثابت و مخارج پیش از تولید را بدون بهره سرمایه‌ای در جریان نقدی کل سرمایه منظور کنید؛ بهره سرمایه‌ای در هزینه تأمین مالی/ساخت و جلوگیری از دوباره‌شماری جداگانه تطبیق داده شود.','تغییر خالص سرمایه در گردش را در دوره وقوع به‌عنوان خروج/ورود نقدی ثبت کنید.','در دوره بازیافت، ارزش باقیمانده دارایی و بازیافت سرمایه در گردش را پس از کسر بدهی‌های تسویه‌نشده لحاظ کنید.'],formulas:['جریان نقدی خالص کل سرمایه = درآمد نقدی عملیاتی و سایر درآمدها − سرمایه‌گذاری ثابت − مخارج پیش از تولید (خالص از بهره) − افزایش سرمایه در گردش − هزینه عملیاتی نقدی − بازاریابی − مالیات نقدی','جریان نقدی سهامدار = مازاد/کسری نقدی پروژه + سود تقسیمی + استرداد سرمایه − آورده سهامدار (با تعریف و علامت‌گذاری یکنواخت)'],example:'برداشت وام و بازپرداخت اصل آن در Cash Flow برنامه‌ریزی مالی ظاهر می‌شود، اما نباید بازده کل سرمایه را بهتر یا بدتر کند؛ در جریان نقدی کل سرمایه این تراکنش‌های تأمین مالی حذف می‌شوند.',checks:['جریان نقدی پروژه از بدهی و آورده مستقل باشد.','جریان نقدی سهامدار تمام تزریق‌های equity را به‌عنوان خروجی و دریافتی‌های مرتبط را با علامت صحیح نشان دهد.','بهره سرمایه‌ای در CAPEX و بهره عملیاتی در OPEX/مالی دوباره‌شماری نشود.','سرمایه در گردش فقط بر مبنای تغییر دوره‌ای وارد جریان نقدی شود، نه کل مانده در همه سال‌ها.'],pitfalls:['استفاده از جریان نقدی پس از تأمین مالی برای محاسبه IRR کل سرمایه.','کسر دوباره بهره یا سرمایه در گردش.','افزودن ارزش اسقاط بدون کسر بدهی و هزینه‌های خاتمه پروژه.']},
{title:'۹-۲. NPV، IRR و MIRR و قرارداد نرخ‌ها',purpose:'هر شاخص باید به جریان نقدی، نرخ تنزیل، ارز، دوره و زمان‌بندی متناظر متصل باشد.',inputs:['بردار جریان نقدی خام و بدون تنزیل به تفکیک دوره','تاریخ/فاصله زمانی هر جریان و نقطه مرجع تنزیل','نرخ تنزیل پروژه و نرخ مورد انتظار سهامدار','نرخ تأمین مالی کسری و نرخ سرمایه‌گذاری مجدد مازاد برای MIRR','ارز و وضعیت اسمی یا واقعی جریان‌ها'],method:['NPV را از جریان نقدی خام هر دوره با یک قرارداد زمانی روشن محاسبه کنید.','IRR را نرخی بیابید که NPV همان بردار خام را صفر می‌کند؛ تعداد تغییر علامت‌ها و احتمال چندگانگی ریشه را گزارش کنید.','برای MIRR نرخ تأمین مالی کسری‌ها و نرخ سرمایه‌گذاری مجدد مازادها را جداگانه مشخص کنید.','برای جریان ماهانه یا میان‌دوره‌ای، فاصله زمانی واقعی را اعمال کنید؛ نرخ سالانه را بدون تبدیل به نرخ دوره‌ای استفاده نکنید.','جریان‌های اسمی را با نرخ اسمی و جریان‌های واقعی را با نرخ واقعی تنزیل کنید؛ ارز جریان و نرخ نیز هم‌خوان باشد.'],formulas:['NPV = Σ CF_t / (1 + r)^t + ارزش فعلی ارزش اسقاط','IRR: نرخی که NPV(CF,r)=0','MIRR = (FV مثبت‌ها با نرخ سرمایه‌گذاری مجدد / PV قدرمطلق منفی‌ها با نرخ تأمین مالی)^(1/n) − 1'],example:'اگر یک جدول اکسل قبلاً جریان نقدی را تنزیل کرده باشد، جمع‌زدن آن برای NPV مجاز است؛ اما محاسبه مجدد NPV با تنزیل همان ردیف، تنزیل مضاعف و نتیجه نادرست می‌سازد.',checks:['ورودی تابع NPV/IRR جریان نقدی خام باشد، نه ردیف Discounted Cash Flow.','دوره t=0 و زمان اولین پرداخت در قرارداد محاسبه مشخص باشد.','نرخ MIRR و افق زمانی در گزارش درج شود.','در صورت چند IRR یا نبود ریشه، وضعیت به‌جای یک عدد قطعی گزارش شود.'],pitfalls:['مقایسه IRR پروژه با هزینه حقوق صاحبان سهام یا IRR سهامدار با WACC.','مخلوط کردن نرخ اسمی و واقعی یا ارزهای مختلف.','فرض ضمنی سرمایه‌گذاری مجدد همه مازادها با نرخ IRR در تفسیر IRR.']},
{title:'۹-۳. خروجی‌ها، صورت‌های مالی و کنترل تطبیق',purpose:'نتایج باید از جداول ورودی تا صورت‌های مالی و شاخص‌های ارزیابی قابل ردیابی باشند.',inputs:['خلاصه پروژه و هزینه‌های سرمایه‌گذاری','هزینه تولید، تولید و فروش، منابع مالی','Cash Flow برنامه‌ریزی مالی و Discounted Cash Flow کل سرمایه','Discounted Cash Flow حقوق صاحبان سهام','صورت سود و زیان، ترازنامه و نقطه سربه‌سر','دوره بازگشت ساده و پویا، نسبت‌های پوشش بدهی و کارایی'],method:['خلاصه سرمایه‌گذاری را با CAPEX، مخارج پیش از تولید، بهره ساخت و سرمایه در گردش تطبیق دهید.','برنامه تولید و فروش را با ظرفیت، Ramp-up، بازده و محدودیت بازار تطبیق دهید.','صورت سود و زیان را از درآمد، بهای تمام‌شده، استهلاک، هزینه مالی و مالیات بازسازی کنید.','ترازنامه را از دارایی ثابت خالص، سرمایه در گردش، نقد، بدهی و حقوق صاحبان سهام کنترل کنید.','NPV، IRR، MIRR و Payback را جدا برای کل سرمایه و سهامدار گزارش کنید.','نسبت‌های پوشش خدمت بدهی را در تک‌تک سال‌های بازپرداخت و نه فقط به‌صورت میانگین کنترل کنید.'],formulas:['سرمایه در گردش خالص = دارایی جاری عملیاتی − بدهی جاری عملیاتی','DSCR_t = جریان نقدی در دسترس خدمت بدهی_t / (اصل بدهی_t + بهره و کارمزد_t)','دوره بازگشت ساده: اولین دوره‌ای که جریان نقدی تجمعی نامنفی می‌شود','دوره بازگشت پویا: اولین دوره‌ای که NPV تجمعی با نرخ مربوط نامنفی می‌شود'],example:'پروژه‌ای با NPV مثبت ممکن است در یک سال خاص نقدینگی کافی برای پرداخت قسط نداشته باشد؛ NPV مثبت جایگزین کنترل Cash Flow و DSCR سالانه نیست.',checks:['جمع منابع و مصارف در هر دوره و کل دوره برابر باشد یا شکاف صریح گزارش شود.','مانده وام با برداشت، بهره و بازپرداخت اصل تطبیق داشته باشد.','تغییر نقد و سرمایه در گردش در ترازنامه با جریان نقدی سازگار باشد.','Payback ساده و پویا با یکدیگر اشتباه نشوند.'],pitfalls:['گزارش یک عدد IRR بدون مشخص‌کردن مبنای پروژه یا سهامدار.','تطبیق ندادن ترازنامه و جریان نقدی.','پنهان‌کردن کسری نقدینگی در میانگین‌های سالانه.']},
{title:'۹-۴. تحلیل اقتصادی، آثار توسعه‌ای و پایداری',purpose:'تفکیک توجیه مالی سرمایه‌گذار از ارزش اقتصادی/اجتماعی پروژه برای اقتصاد و ذی‌نفعان.',inputs:['قیمت‌های بازار و تعدیلات قیمت سایه‌ای','مالیات، عوارض، یارانه و انتقالات مالی','نرخ ارز سایه‌ای و نرخ تنزیل اقتصادی','ارزش افزوده، اشتغال مستقیم و غیرمستقیم','مصرف انرژی و آب، انتشار و آثار محیط‌زیستی'],method:['ابتدا مرز تحلیل مالی بنگاه را تثبیت کنید.','برای تحلیل اقتصادی، مالیات و یارانه و سایر انتقالات را طبق روش منتخب از هزینه/فایده اقتصادی تفکیک کنید.','قیمت‌های بازار را فقط با مستندات و ضرایب قابل دفاع به قیمت اقتصادی تعدیل کنید.','ارزش افزوده، اشتغال و آثار ارزی را جدا از سودآوری مالی گزارش کنید.','شاخص‌های محیط‌زیستی و پایداری را با واحد، مرز محاسبه و منبع داده ثبت کنید.'],formulas:['ارزش افزوده ناخالص = ارزش ستانده − مصرف واسطه','ارزش افزوده خالص = ارزش افزوده ناخالص − استهلاک','خالص اثر ارزی = ورودی ارزی − خروجی ارزی (با تعریف مرز پروژه)'],example:'یارانه انرژی ممکن است هزینه مالی بنگاه را کاهش دهد، اما لزوماً به همان میزان منفعت اقتصادی برای کشور ایجاد نمی‌کند؛ این دو دیدگاه باید جدا گزارش شوند.',checks:['تحلیل اقتصادی با جریان نقدی مالی مخلوط نشود.','قیمت سایه‌ای، نرخ ارز سایه‌ای و نرخ تنزیل اقتصادی منبع و تاریخ داشته باشند.','اشتغال و آثار زیست‌محیطی دوباره‌شماری نشوند.'],pitfalls:['معرفی NPV مالی به‌عنوان ارزش اقتصادی ملی.','اعمال ضرایب تعدیل فاقد مستندات.']}
]}

]

